<div class="my-block"><el-tooltip effect="light" style="padding:0px;margin:0px;" placement="left-start"><template #content v-if="props.allMes.playingNow===props.allMes.allMesMy.playerNow.name"> <div class="head-buttons-block"><div class="head-buttons" @click="changeMonster">换人</div><div class="head-buttons">放弃</div></div></template><div class="my-header"></div></el-tooltip><div class="my-header-mes"><el-progress style="position:relative;margin-bottom: 4px;" :percentage="getLifeNow(props.allMes.allMesMy.playerNow)" :text-inside="true" :stroke-width="6" color="#ffe3e3"></el-progress><div class="my-header-power" v-for="(power,index) in powerList"><div class="my-header-power-light" v-if="index&lt;props.allMes.allMesMy.playerNow.power"></div></div></div><div class="my-life"><el-progress style="position:relative;" :percentage="getLifeNow(props.allMes.allMesMy.monsterNow)" :text-inside="true" :stroke-width="16" color="#ffe3e3"><div class="progress-position">{{props.allMes.allMesMy.monsterNow.lifeNow}}</div></el-progress><div class="card-list" v-show="isShowCards()"><div class="hand-one" v-for="(hand,index) in props.allMes.allMesMy.handCardList" :style="getHandStyle(index)" @click="choiceCard(index)"><div class="hand-one-name">{{hand.name}}</div><el-tooltip effect="light" placement="top"><template #content> <div style="max-width: 200px;font-size: 12px;color:#666;">{{hand.desc}}</div></template><div class="hand-one-tip"> </div></el-tooltip></div></div><div class="card-num" v-if="isShowCards()">{{props.allMes.allMesMy.handCardList.length}}</div><div class="skill-list" v-show="isShowSkill()"><div class="skill-one" v-for="(skill,index) in props.allMes.allMesMy.monsterNow.skillList" :style="getSkillStyle(index)" @click="choiceSkill(index)"><div class="skill-one-name">{{skill}}</div><el-tooltip effect="light" placement="top"><template #content> <div style="max-width: 200px;font-size: 12px;color:#666;">{{skillListApi.getSkillByName(skill).desc}}</div></template><div class="skill-one-tip"> </div></el-tooltip></div></div></div></div>